#include "exotic/cognition/agency_executive.hpp"
#include <cassert>
#include <cstdio>
using namespace exotic::cognition;
int main(){const char*db="agency_exec_test.sqlite";std::remove(db);AgentStore store(db);store.initialize();AgencyExecutive exec(store);Intention i{"i1","investigate","c1","committed",.8,"chosen"};Intention alt{"i2","alternate","c2","tentative",.6,"available"};AgencyInput in;in.subject="investigate anomaly";in.options={{"inspect","inspect evidence",.8,.7,.6,.5,.9,.1,.1},{"ignore","ignore for now",.1,.1,.1,.1,.2,0,0}};in.intention_demands={{i,.8,.9,.1,.1,{},{}}};in.temporal_options={{i,0,900,0,0,.8,.5,0,false}};in.reconsiderations={{i,{.8,.7,.6,.5,.2,.9},alt}};in.uncertainty=.8;in.stakes=.8;in.now=1000;in.external_action_requested=true;in.explicit_external_grant=false;auto c=exec.consider(in);assert(!c.id.empty());assert(c.volition.outcome==VolitionOutcome::Choose);assert(c.metacognition.engage);assert(!c.arbitration.assignments.empty());assert(!c.timing.empty());assert(c.timing.front().choice==TemporalChoice::Review);assert(c.reconsideration.size()==1);assert(c.reconsideration.front().review_worthwhile);assert(!c.external_action_authorized);assert(exec.persist_cycle(in,c,"2026-09-09T04:38:00Z"));auto before=store.goals().size();auto r=exec.remember_choice(in.subject,c.volition,"2026-09-09T04:38:00Z");assert(!r.id.empty());assert(store.goals().size()==before);in.explicit_external_grant=true;auto c2=exec.consider(in);assert(c2.external_action_authorized);assert(exec.persist_cycle(in,c2,"2026-09-09T04:39:00Z"));std::remove(db);std::remove("agency_exec_test.sqlite-wal");std::remove("agency_exec_test.sqlite-shm");return 0;}
